import fs from "node:fs";
import path from "node:path";

const out = path.dirname(new URL(import.meta.url).pathname.replace(/^\/(.:)/, "$1"));
const evidence = path.join(out, "evidence");
fs.mkdirSync(evidence, { recursive: true });

const q = value => `"${String(value ?? "").replaceAll('"', '""').replaceAll(/\r?\n/g, " ")}"`;
const csv = (headers, rows) => [headers.map(q).join(","), ...rows.map(row => headers.map(h => q(row[h])).join(","))].join("\n") + "\n";
const write = (name, body) => fs.writeFileSync(path.join(out, name), body.endsWith("\n") ? body : body + "\n", "utf8");

