const specs = [];
const add = (uc, prefix, persona, priority, type, automation, result, evidenceRef, scenarios, expectedState="State remains valid and internally consistent") => {
  for (const title of scenarios) {
    const id = `TC-${prefix}-${String(specs.filter(t => t.prefix === prefix).length + 1).padStart(3,"0")}`;
    specs.push({
      prefix,id,uc,title,persona,priority,type,
      Preconditions:`${useCases.find(u=>u.id===uc)?.pre}. Use only unique synthetic data.`,
      "Test Data":`Deterministic QA run id; scenario: ${title}`,
      Environment:"Named dev tunnel; frontend dev.rehletshifaa.com; API through api-dev/gateway; Keycloak; PostgreSQL; MinIO; Redis; Mailpit",
      "Detailed Steps":`1. Establish the persona and stated precondition. 2. Capture the initial UI, API response and workflow state. 3. Perform: ${title}. 4. Refresh/reload and query the authoritative downstream view. 5. Verify persistence, work/action ownership, notification and duplicate counts.`,
      "Expected UI Result":`The control gives a clear, localized result for '${title}' and never claims success without the business outcome.`,
      "Expected API Result":`The request is accepted exactly once when valid; invalid, stale or unauthorized input is rejected without side effects.`,
      "Expected HTTP Status":title.match(/invalid|missing|unsupported|wrong|unauthorized|foreign|expired|stale|premature|negative|zero-byte|oversized|without/i) ? "4xx appropriate to contract (400/401/403/404/409/429)" : "2xx appropriate to contract",
      "Expected Domain/Workflow State":expectedState,
      "Expected Database/Persistence Result":"One canonical record/event where applicable; no duplicate patient, case, assignment, work item, proposal, deposit event or notification.",
      "Expected WorkItem/PatientAction":"Exactly the active work/action required by the resulting milestone; completed history does not drive currentAction.",
      "Expected WaitingOn/currentAction":"Matches the accountable actor after the operation; no stale action survives progression.",
      "Expected Notification/Event":"Exactly one logical event for a successful state change; none for rejected requests unless an audit event is specified.",
      "Expected Email Recipient/Template":"Correct accountable synthetic recipient and role-specific wording; no wrong-recipient copy and no unnecessary PII.",
      "Expected Audit/Event Record":"Actor, case/version, reason and timestamp captured where supported; correlation ID available at the gateway.",
      Cleanup:"Do not delete volumes. Keep uniquely identified QA records or use isolated H2/mocked fixtures.",
      "Automation Status":automation,"Actual Result":result === "PASS" ? "Matched expected result in the cited automated execution." : result === "BLOCKED" ? "Not executed because the cited environment/harness prerequisite was unavailable." : "Not executed in this pass; retained for manual/exploratory execution.",
      Result:result,"Evidence Reference":evidenceRef,"Defect ID":result === "BLOCKED" ? "QA-ENV-001" : ""
    });
  }
};

